div.script:
document.addEventListener('DOMContentLoaded', function() {
    const rows = document.querySelectorAll('.clickable-row');
    rows.forEach(function(row) {
        row.addEventListener('click', function(e) {
            // Don't navigate if clicking on a button or link
            if (e.target.closest('a') || e.target.closest('button')) {
                return;
            }
            const href = this.getAttribute('data-href');
            if (href) {
                window.location.href = href;
            }
        });
    });
});

form.script:
let jobPositionIndex = 0;

document.addEventListener('DOMContentLoaded', function() {
    // Add first job position on load
    addJobPosition();

    // Get submit button
    const submitBtn = document.querySelector('button[name="button_submit"]');
    const form = document.getElementById('recruitment_form');

    // Function to validate all required fields
    function validateForm() {
        const workLocation = document.querySelector('input[name="work_location"]');
        const container = document.getElementById('job_positions_container');
        const jobs = container.querySelectorAll('[id^="job_position_"]');

        // Check work location (required)
        if (!workLocation || !workLocation.value.trim()) {
            return false;
        }

        // Check if at least one job has all required fields filled
        let hasValidJob = false;
        jobs.forEach(job => {
            const jobTitle = job.querySelector('input[name*="[job_title]"]');
            const contractType = job.querySelector('select[name*="[emp_contract_type]"]');
            const numPositions = job.querySelector('input[name*="[no_of_positions]"]');
            const description = job.querySelector('textarea[name*="[job_description]"]');

            if (jobTitle && jobTitle.value.trim() !== '' &&
                contractType && contractType.value !== '' &&
                numPositions && numPositions.value && parseInt(numPositions.value) > 0 &&
                description && description.value.trim() !== '') {
                hasValidJob = true;
            }
        });

        return hasValidJob;
    }

    // Function to update submit button state
    function updateSubmitButton() {
        if (submitBtn) {
            const isValid = validateForm();
            submitBtn.disabled = !isValid;
            if (isValid) {
                submitBtn.classList.remove('disabled');
            } else {
                submitBtn.classList.add('disabled');
            }
        }
    }

    // Initial button state
    updateSubmitButton();

    // Add event listeners to all form inputs
    if (form) {
        form.addEventListener('input', updateSubmitButton);
        form.addEventListener('change', updateSubmitButton);

        // Add form validation on submit
        form.addEventListener('submit', function(e) {
            const clickedButton = document.activeElement;

            // Only validate if submit button was clicked (not save draft)
            if (clickedButton && clickedButton.name === 'button_submit') {
                if (!validateForm()) {
                    e.preventDefault();
                    alert('Please fill in all required fields:\n- Work Location\n- At least one job position with: Job Title, Number of Positions, Contract Type, and Job Description');
                    return false;
                }
            }
        });
    }
});

function addJobPosition() {
    const container = document.getElementById('job_positions_container');
    const template = document.getElementById('job_position_template');
    const clone = template.cloneNode(true);

    clone.style.display = 'block';
    clone.id = `job_position_${jobPositionIndex}`;
    clone.removeAttribute('id');

    // Get the inner div (job-position-card)
    const card = clone.querySelector('.job-position-card');
    if (!card) {
        console.error('No job-position-card found in template');
        return;
    }

    // Create wrapper div with proper ID
    const wrapper = document.createElement('div');
    wrapper.id = `job_position_${jobPositionIndex}`;
    wrapper.appendChild(card);

    // Replace INDEX in all name attributes
    const inputs = wrapper.querySelectorAll('input, select, textarea');
    inputs.forEach(input => {
        if (input.name && input.name.includes('INDEX')) {
            input.name = input.name.replace(/INDEX/g, jobPositionIndex);
        }
    });

    // Update position number
    const posNumSpan = wrapper.querySelector('.position-num');
    if (posNumSpan) {
        posNumSpan.textContent = jobPositionIndex + 1;
    }

    container.appendChild(wrapper);

    // Setup skills management for this job position
    setupSkillsForJob(wrapper, jobPositionIndex);

    // Hide remove button if only one job
    updateRemoveButtons();

    jobPositionIndex++;

    // Trigger validation after adding new position
    const submitBtn = document.querySelector('button[name="button_submit"]');
    if (submitBtn) {
        const event = new Event('input', { bubbles: true });
        document.getElementById('recruitment_form').dispatchEvent(event);
    }
}

function removeJobPosition(btn) {
    const jobCard = btn.closest('.job-position-card').parentElement;
    jobCard.remove();
    updateRemoveButtons();
    updatePositionNumbers();

    // Trigger validation after removing position
    const submitBtn = document.querySelector('button[name="button_submit"]');
    if (submitBtn) {
        const event = new Event('input', { bubbles: true });
        document.getElementById('recruitment_form').dispatchEvent(event);
    }
}

function updateRemoveButtons() {
    const container = document.getElementById('job_positions_container');
    const jobs = container.querySelectorAll('[id^="job_position_"]');
    jobs.forEach((job, index) => {
        const removeBtn = job.querySelector('.remove-job-btn');
        if (removeBtn) {
            removeBtn.style.display = jobs.length === 1 ? 'none' : 'inline-block';
        }
    });
}

function updatePositionNumbers() {
    const container = document.getElementById('job_positions_container');
    const jobs = container.querySelectorAll('[id^="job_position_"]');
    jobs.forEach((job, index) => {
        const numSpan = job.querySelector('.position-num');
        if (numSpan) {
            numSpan.textContent = index + 1;
        }
    });
}

function setupSkillsForJob(jobElement, index) {
    const skillTypeSelect = jobElement.querySelector('.skill_type_select');
    const skillSelect = jobElement.querySelector('.skill_select');
    const addBtn = jobElement.querySelector('.add_skill_btn');
    const badgesContainer = jobElement.querySelector('.skills_badges');
    const hiddenInput = jobElement.querySelector('.job_skill_ids_input');
    let selectedSkills = [];

    skillTypeSelect.addEventListener('change', async function() {
        if (this.value) {
            skillSelect.disabled = false;
            try {
                const response = await fetch('/my/recruitment/get_skills', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                    },
                    body: JSON.stringify({
                        jsonrpc: '2.0',
                        method: 'call',
                        params: {
                            skill_type_id: this.value
                        },
                        id: Math.floor(Math.random() * 1000000)
                    })
                });
                const data = await response.json();
                const skills = data.result || [];
                skillSelect.innerHTML = 'Select Skill...';
                skills.forEach(skill => {
                    const option = document.createElement('option');
                    option.value = skill.id;
                    option.textContent = skill.name;
                    skillSelect.appendChild(option);
                });
            } catch (error) {
                console.error('Error fetching skills:', error);
            }
        } else {
            skillSelect.disabled = true;
            skillSelect.innerHTML = 'Select Skill...';
        }
    });

    skillSelect.addEventListener('change', function() {
        addBtn.disabled = !this.value;
    });

    addBtn.addEventListener('click', function() {
        const skillId = parseInt(skillSelect.value);
        const skillName = skillSelect.options[skillSelect.selectedIndex].text;

        if (!selectedSkills.includes(skillId)) {
            selectedSkills.push(skillId);

            const badge = document.createElement('span');
            badge.className = 'badge bg-primary';
            badge.innerHTML = `${skillName} `;
            badge.id = `skill_badge_${index}_${skillId}`;
            badge.querySelector('i').addEventListener('click', function() {
                selectedSkills = selectedSkills.filter(id => id !== skillId);
                badge.remove();
                hiddenInput.value = selectedSkills.join(',');
            });
            badgesContainer.appendChild(badge);

            hiddenInput.value = selectedSkills.join(',');
        }

        skillTypeSelect.value = '';
        skillSelect.innerHTML = 'Select Skill...';
        skillSelect.disabled = true;
        addBtn.disabled = true;
    });
}

div.script:
let positionCounter = ;

function addJobPosition() {
    positionCounter++;
    const template = document.getElementById('job-position-template').innerHTML;
    const newPosition = template.replace(/__INDEX__/g, positionCounter - 1).replace(/__NUMBER__/g, positionCounter);

    const container = document.getElementById('job-positions-container');
    container.insertAdjacentHTML('beforeend', newPosition);

    updatePositionNumbers();
}

function removeJobPosition(button) {
    const card = button.closest('.job-position-card');
    const lineId = card.getAttribute('data-line-id');

    // If has line_id, mark for deletion
    if (lineId) {
        const input = document.createElement('input');
        input.type = 'hidden';
        input.name = 'delete_line_ids[]';
        input.value = lineId;
        card.appendChild(input);
        card.style.display = 'none';
    } else {
        // New position, just remove
        card.remove();
    }

    updatePositionNumbers();
}

function updatePositionNumbers() {
    const cards = document.querySelectorAll('#job-positions-container .job-position-card:not([style*="display: none"])');
    cards.forEach((card, index) => {
        card.querySelector('.position-number').textContent = index + 1;
    });
}

document.addEventListener('DOMContentLoaded', function() {
    const skillTypeSelect = document.getElementById('edit_skill_type_id');
    const skillSelect = document.getElementById('edit_skill_id');
    const addBtn = document.getElementById('edit_add_skill_btn');
    const badgesContainer = document.getElementById('edit_skills_badges');
    const hiddenInput = document.getElementById('edit_job_skill_ids_input');
    let selectedSkills = hiddenInput.value ? hiddenInput.value.split(',').map(Number) : [];

    skillTypeSelect.addEventListener('change', async function() {
        if (this.value) {
            skillSelect.disabled = false;
            // Fetch skills by type using JSON-RPC
            try {
                const response = await fetch('/my/recruitment/get_skills', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                    },
                    body: JSON.stringify({
                        jsonrpc: '2.0',
                        method: 'call',
                        params: {
                            skill_type_id: this.value
                        },
                        id: Math.floor(Math.random() * 1000000)
                    })
                });
                const data = await response.json();
                const skills = data.result || [];
                skillSelect.innerHTML = 'Select Skill...';
                skills.forEach(skill => {
                    const option = document.createElement('option');
                    option.value = skill.id;
                    option.textContent = skill.name;
                    skillSelect.appendChild(option);
                });
            } catch (error) {
                console.error('Error fetching skills:', error);
            }
        } else {
            skillSelect.disabled = true;
            skillSelect.innerHTML = 'Select Skill...';
        }
    });

    skillSelect.addEventListener('change', function() {
        addBtn.disabled = !this.value;
    });

    addBtn.addEventListener('click', function() {
        const skillId = parseInt(skillSelect.value);
        const skillName = skillSelect.options[skillSelect.selectedIndex].text;

        if (!selectedSkills.includes(skillId)) {
            selectedSkills.push(skillId);

            const badge = document.createElement('span');
            badge.className = 'badge bg-primary';
            badge.innerHTML = `${skillName} `;
            badge.id = `edit_skill_badge_${skillId}`;
            badgesContainer.appendChild(badge);

            hiddenInput.value = selectedSkills.join(',');
        }

        skillTypeSelect.value = '';
        skillSelect.innerHTML = 'Select Skill...';
        skillSelect.disabled = true;
        addBtn.disabled = true;
    });

    window.removeEditSkill = function(skillId) {
        selectedSkills = selectedSkills.filter(id => id !== skillId);
        document.getElementById(`edit_skill_badge_${skillId}`).remove();
        hiddenInput.value = selectedSkills.join(',');
    };
});
